cessing: '=>'Текущая обработка: ','Importing... Please Wait...'=>'Импортируется... Пожалуйста, подождите...','Please Wait...'=>'Пожалуйста, подождите...','Retry'=>'Повторить','Active'=>'Активно','Deactivating...'=>'Деактивация...','Activating...'=>'Активация...','Installing...'=>'Установка...','Install'=>'Установить','Skip to content'=>'Перейти к содержимому','Write a comment&hellip;'=>'Написать комментарий&hellip;','Log out?'=>'Выйти?','Log out of this account'=>'Выйти из этой учетной записи','Logged in as'=>'Зашли как','You must be %1$slogged in%2$s to post a comment.'=>'Вы должны %1$sвойти%2$s, чтобы оставить комментарий.','Next'=>'Далее','Previous'=>'Назад','Comments are closed'=>'Комментарии закрыты','Reply'=>'Ответить','No comments yet. Why don&rsquo;t you start the discussion?'=>'Комментариев пока нет. Почему бы &rsquo;Вам не начать обсуждение?','%s Comment'=>'%s комментарий' . "\0" . '%s комментария' . "\0" . '%s комментариев','Comments'=>'Комментарии','https://peregrine-themes.com/'=>'https://peregrine-themes.com/','Peregrine themes'=>'Peregrine themes','https://peregrine-themes.com/bloghash'=>'https://peregrine-themes.com/bloghash']];